const brand = { name: 'Capital Fence', phone: '501-247-3918', area: 'Little Rock, Arkansas' };
const ns='http://www.w3.org/2000/svg';
function shape(tag,attrs,parent){const el=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v));parent.append(el);return el;}
const boards=document.querySelector('#boards'),posts=document.querySelector('#posts');
for(let i=0;i<48;i++){const x=72+i*20;const g=shape('g',{class:'board'},boards);shape('path',{d:`M${x} 509V353l9-8 9 8v156Z`,fill:'url(#wood)',stroke:'#966041','stroke-width':'.7'},g);shape('path',{d:`M${x} 509V353l9-8 9 8v156Z`,fill:'url(#grain)'},g);shape('circle',{cx:x+9,cy:392,r:1.2,fill:'#785238'},g);shape('circle',{cx:x+9,cy:480,r:1.2,fill:'#785238'},g);}
for(let i=0;i<6;i++){const x=65+i*194;const g=shape('g',{class:'post'},posts);shape('rect',{x,y:334,width:24,height:182,rx:1,fill:'#a86b44'},g);shape('path',{d:`M${x-3} 334l15-10 15 10v6h-30Z`,fill:'#dba176'},g);shape('rect',{x:x+17,y:341,width:7,height:175,fill:'#865537'},g);}
const clamp=x=>Math.max(0,Math.min(1,x));const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let playing=false;
function render(p){p=reduced?1:p;document.querySelectorAll('.post').forEach((e,i)=>{const n=clamp((p-i*.025)/.24);e.style.opacity=n;e.style.transform=`translateY(${(1-n)*80}px)`});document.querySelector('#rails').style.opacity=clamp((p-.2)/.2);document.querySelectorAll('.board').forEach((e,i)=>{const n=clamp((p-.32-i*.008)/.23);e.style.opacity=n;e.style.transform=`translateY(${(1-n)*-95}px)`});document.querySelector('#progress').style.width=`${p*100}%`;const stage=p<.3?0:p<.72?1:2;document.querySelector('#stage').textContent=['01 / SET THE POSTS','02 / BUILD THE BOUNDARY','03 / MAKE IT YOURS'][stage];document.querySelector('.scene-no').textContent=`0${stage+1} — 03`;}
function update(){if(!playing){const s=document.querySelector('.scroll-hero');render(clamp(-s.getBoundingClientRect().top/(s.offsetHeight-innerHeight)));}}
let ticking=false;addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(()=>{update();ticking=false});ticking=true}},{passive:true});addEventListener('resize',update);update();
document.querySelector('#play').onclick=()=>{if(playing)return;playing=true;let start;const animate=t=>{start??=t;const p=clamp((t-start)/5000);render(p);if(p<1)requestAnimationFrame(animate);else playing=false;};requestAnimationFrame(animate)};
const quote=document.querySelector('#quote');document.querySelector('#estimate').onclick=()=>quote.showModal();document.querySelectorAll('.close,.close-button').forEach(b=>b.onclick=()=>quote.close());quote.addEventListener('click',e=>{if(e.target===quote){const r=quote.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)quote.close();}});
